guess: .word 0:5
answer: .word 0 # char* to dictionary

# MARK: Main

.text

.globl main
main:
    # Load a random word into `answer`
    la $t0, dictionary # FIXME: Choose random word rather than dictionary[0]
    sw $t0, answer

    # Clear display by drawing an all white rectangle the size of the framebuffer
    li $a0, 0 # x
    li $a1, 0 # y
    li $a2, FRAMEBUFFER_WIDTH # w
    li $a3, FRAMEBUFFER_HEIGHT # h
    addiu $sp, $sp, -20
    li $t0, COLOR_WHITE # color (white)
    sw $t0, 16($sp)
    jal gfx_draw_rect
    addiu $sp, $sp, 20

    # Draw an empty game board
    jal gfx_draw_board

    # Main game loop
    input_loop:
        jal keyboard_poll_input # Get keyboard input

        beq $v0, 8, handle_backspace # Handle backspace (ASCII Backspace Control, 0x8)

        # Handle enter/return
        beq $v0, 10, handle_enter # ASCII LF Control

        handle_character:
            # Convert lowercase input to uppercase. This procedure returns 0 if the input is
            # nonalphabetic, so it doubles as input validation to disallow numbers/symbols in guesses.
            move $a0, $v0
            jal to_ascii_uppercase
            beqz $v0, input_loop # ignore non-alphabetic characters

            lw $t0, cursor_index # cursor_index <- $v0
            beq $t0, 5, input_loop # limit user input to 5 letters

            # guess[cursor_index] = char
            sll $t0, $t0, 2
            sw $v0, guess($t0)

            # Draw tile
            move $a0, $v0
            lw $a1, cursor_x
            lw $a2, cursor_y
            li $a3, TILE_GUESS
            jal gfx_draw_tile

            # Move right one tile

            # cursor_index += 1
            lw $t0, cursor_index
            addiu $t0, $t0, 1
            sw $t0, cursor_index

            # cursor_x += 1
            lw $t0, cursor_x
            addiu $t0, $t0, 31
            sw $t0, cursor_x

            j input_loop # next input

        handle_enter:
            # Don't allow enter key if the cursor isn't at the end of the board
            lw $t0, cursor_index
            blt $t0, 5, input_loop

            # Don't allow enter key if the guess isn't in the dictionary

            # Grade the current submission
            addiu $sp, $sp, -8
            li $t0, 52 # x = 52
            sw $t0, 0($sp)
            sw $zero, 4($sp) # index = 0

            check_loop:
                la $a0, guess
                lw $a1, answer
                lw $a2, 4($sp) # index
                jal check_letter

                # Draw tile based on judgement
                lw $t0, 4($sp) # $t0 <- index
                sll $t0, $t0, 2 # index to offset
                lbu $a0, guess($t0) # letter
                lw $a1, 0($sp) # x
                lw $a2, cursor_y # y
                move $a3, $v0 # tile type
                jal gfx_draw_tile

                # x += 31
                lw $t0, 0($sp)
                addiu $t0, $t0, 31
                sw $t0, 0($sp)

                # index += 1
                lw $t0, 4($sp)
                addiu $t0, $t0, 1
                sw $t0, 4($sp)

                # Exit loop if we've completed the grade (index == 5)
                bne $t0, 5, check_loop

            addiu $sp, $sp, 8

            # Exit the game if all guesses are exhausted
            lw $t0, cursor_y
            beq $t0, 191, sys_exit

            # Move down one tile

            # cursor_index = 0
            li $t0, 0
            sw $t0, cursor_index

            # cursor_x = 52
            li $t0, 52
            sw $t0, cursor_x

            # cursor_y += 31
            lw $t0, cursor_y
            addiu $t0, $t0, 31
            sw $t0, cursor_y

            j input_loop # next input

        handle_backspace:
            lw $t0, cursor_index
            beqz $t0, input_loop # if index == 0, continue

            # Move left one tile
            
            # cursor_index -= 1
            lw $t0, cursor_index
            addiu $t0, $t0, -1
            sw $t0, cursor_index

            # cursor_x -= 31
            lw $t0, cursor_x
            addiu $t0, $t0, -31
            sw $t0, cursor_x

            # Draw TILE_EMPTY at this spot
            li $a0, 0 # no letter
            lw $a1, cursor_x # x = cursor_x
            lw $a2, cursor_y # y = cursor_y
            li $a3, TILE_EMPTY
            jal gfx_draw_tile

            j input_loop # next input

    j sys_exit

# MARK: Syscalls

# syscall 10: Exit
sys_exit:
    li $v0, 10
    syscall
    jr $ra

# syscall 11: Print Character
sys_print_char:
    li $v0, 11
    syscall
    jr $ra

# syscall 42: random int range
sys_rand_range:
    li $v0, 42 # random int syscall
    syscall # V0 gets random number
    jr $ra

# MARK: Input

# Spins the CPU until keyboard input is available, returning the key input by the user.
keyboard_poll_input:
    # Spin until ready bit is set
    lw $t0, KEYBOARD_RX_CONTROL_REG
    andi $t0, $t0, 0x1 # mask upper 31 bits
    beqz $t0, keyboard_poll_input # check READY bit

    keyboard_read_data:
        # Return user input
        lbu $v0, KEYBOARD_RX_DATA_REG
        jr $ra

dictionary_contains_word:
    jr $ra

# Checks if a letter is in the word.
#
# Arguments: 
#   $a0: guess
#   $a1: answer
#   $a2: position
#
# Returns:
#   TILE_GREEN: correct letter, correct position
#   TILE_YELLOW: letter exists elsewhere in word
#   TILE_GRAY: letter not in word
#
# Usage check_letter(guess, answer, position)
check_letter:
    # load answer[position]
    addu $t1, $a1, $a2  # t1 = answer + position
    lbu $t2, ($t1)  # t2 = answer[position]

    # load guess[position]
    sll $a2, $a2, 2 # 4-byte aligned, so position *= 4
    addu $t0, $a0, $a2  # t0 = guess + position
    lbu $t3, ($t0) # t3 = guess[position]

    # if equal, return TILE_COLOR_GREEN
    beq $t3, $t2, letter_correct_position

    # If not at correct position, scan entire word.
    # Not bothering with a loop here, since words are fixed-length and unterminated.
    lbu $t4, 0($a1)
    beq $t4, $t3, letter_found_elsewhere
    lbu $t4, 1($a1)
    beq $t4, $t3, letter_found_elsewhere
    lbu $t4, 2($a1)
    beq $t4, $t3, letter_found_elsewhere
    lbu $t4, 3($a1)
    beq $t4, $t3, letter_found_elsewhere
    lbu $t4, 4($a1)
    beq $t4, $t3, letter_found_elsewhere

    letter_not_found:
        li $v0, TILE_GRAY
        jr $ra
    letter_found_elsewhere:
        li $v0, TILE_YELLOW
        jr $ra
    letter_correct_position:
        li $v0, TILE_GREEN
        jr $ra

# Validates user input by converting the input character to uppercase, or returning 0 if the
# character is nonalphabetic.
#
# Arguments:
#   $a0: Input ASCII character
to_ascii_uppercase:
    andi $a0, $a0, 0xDF # Convert to uppercase by setting bit 5 (char & 0b11011111)

    # Validate range by checking that 'A' < char < 'Z'
    li $t0, 'A'
    blt $a0, $t0, not_alphabetic
    li $t0, 'Z'
    bgt $a0, $t0, not_alphabetic

    # It's alphabetic
    move $v0, $a0
    jr $ra

    # Return NULL (\0) if the character isn't alphabetic
    not_alphabetic:
        move $v0, $zero
        jr $ra

# MARK: Graphics

# Draws a filled rectangle at (x, y) with given width, height, and color.
#
# Arguments:
#   $a0: x (in pixels)
#   $a1: y (in pixels)
#   $a2: width (in pixels)
#   $a3: height (in pixels)
#   color is passed on the stack at 16($sp)
#
# Usage:
#   gfx_draw_rect(x, y, width, height, color)
gfx_draw_rect:
    beq $a2, $zero, rect_rtn # zero width → nothing to draw
    beq $a3, $zero, rect_rtn # zero height → nothing to draw

    lw $t0, 16($sp) # load color argument from the stack

    la $t1, framebuffer  # base addr of framebuffer

    # Compute x2 = x + width
    add $t5, $a0, $a2

    # Compute y2 = y + height
    add $t6, $a1, $a3

    # Convert x, x2 into byte offsets: x * 4
    sll $a0, $a0, 2 # x1_scaled
    sll $t5, $t5, 2 # x2_scaled

    # Convert y, y2 into byte offsets: y * (512 * 4) = y << 11
    sll $a1, $a1, FRAMEBUFFER_STRIDE_SHIFT # y1_scaled
    sll $t6, $t6, FRAMEBUFFER_STRIDE_SHIFT # y2_scaled

    # Compute starting ($a1) and ending ($t6) addresses
    addu $t2, $t1, $a1 # base + y1_scaled
    addu $a1, $t2, $a0 # first row, left pixel

    addu $t6, $t6, $t1 # base + y2_scaled
    addu $t6, $t6, $a0 # last row, left pixel of last row

    addu $t2, $t2, $t5 # first row, right pixel end

    # Draw the thing
    y_loop:
        move $t3, $a1 # t3 = pointer to left pixel of current row

        x_loop:
            sw $t0, ($t3) # write color to framebuffer
            addiu $t3, $t3, 4 # next pixel
            bne $t3, $t2, x_loop

        addiu $a1, $a1, FRAMEBUFFER_STRIDE # Move downward one row (left edge)
        addiu $t2, $t2, FRAMEBUFFER_STRIDE # Move downward one row (right edge)
        bne $a1, $t6, y_loop # next column

    rect_rtn:
        jr $ra

# Draws a monospaced character bitmap at (x, y) with the given color.
#
# Arguments:
#   $a0: character (ASCII)
#   $a1: x (in pixels)
#   $a2: y (in pixels)
#   $a3: color (in 0x00RRGGBB format)
#
# Usage:
#   gfx_draw_char(character, x, y, color)
gfx_draw_char:
    sll $a0, $a0, 2 # offset on the font table in bytes

    la $t0, framebuffer # base addr of framebuffer

    # Load character bitmap address from font table into $t1
    la $t1, font_table # base address of font table
    add $t1, $t1, $a0 # address of font entry
    lw $t1, ($t1) # address of character bitmap
    
    beqz $t1, char_rtn # if character is not in the font table, don't draw it.

    # Convert x and y into byte offsets: x * 4, y * FRAMEBUFFER_STRIDE
    sll $a1, $a1, 2 # x_scaled
    sll $a2, $a2, FRAMEBUFFER_STRIDE_SHIFT # y_scaled

    # Compute starting address for the current row ($a2).
    addu $a2, $a2, $t0 # base + y_scaled
    addu $a2, $a2, $a1 # + x_scaled

    li $t2, 24 # remaining rows

    row_loop:
        beq $t2, $zero, char_rtn

        # Load one 16-bit row bitmap
        lhu $t3, ($t1) # bitmap mask for this row
        addiu $t1, $t1, 4 # next bitmap row
        li $t5, 16 # remaining pixels on row

        move $t4, $a2 # t4 = write pointer for this row

        bit_loop:
            beqz $t5, next_row

            # Extract MSB (bit 15). If set → draw pixel
            andi $t6, $t3, 0x8000
            beq $t6, $zero, next_bit # don't draw pixel if bit is not set

            sw $a3, ($t4) # draw color

        next_bit:
            # Advance bitmap and framebuffer
            sll $t3, $t3, 1 # next bit to MSB
            addiu $t4, $t4, 4 # advance to next pixel

            addiu $t5, $t5, -1 # remaining_pixels -= 1
            b bit_loop

        next_row:
            addiu $t2, $t2, -1 # remaining_rows -= 1
            addu $a2, $a2, FRAMEBUFFER_STRIDE

            b row_loop

    char_rtn:
        jr $ra

# Draws a null-terminated ASCII-encoded string of text to the given coordinate with the specified
# color.
#
# Arguments:
#   $a0: pointer to string
#   $a1: x
#   $a2: y
#   $a3: color
#
# Usage:
#   gfx_draw_string(string_ptr, x, y, color)
gfx_draw_string:
    str_loop:
        lbu $t0, ($a0) # load character from string pointer
        beqz $t0, str_rtn # stop once we hit a null terminator

        # Save arguments and ra
        addiu $sp, $sp, -20
        sw $ra, 16($sp)
        sw $a3, 12($sp)
        sw $a2, 8($sp)
        sw $a1, 4($sp)
        sw $a0, 0($sp)

        move $a0, $t0 # character is the first argument here
        jal gfx_draw_char
         
        # Restore arguments
        lw $a0, 0($sp)
        lw $a1, 4($sp)
        lw $a2, 8($sp)
        lw $a3, 12($sp)
        lw $ra, 16($sp)
        addiu $sp, $sp, 20

        addiu $a0, $a0, 1 # advance to next character
        addiu $a1, $a1, 16 # advance x by character width (16 pixels)

        j str_loop

    str_rtn:
        jr $ra

# Draws a single letter tile to the framebuffer.
#
# Arguments:
#   $a0: letter (ASCII character byte)
#   $a1: x
#   $a2: y
#   $a3: tile type, 0 = TILE_EMPTY, 1 = TILE_GUESS, 2 = TILE_GRAY, 3 = TILE_YELLOW, 4 = TILE_GREEN
gfx_draw_tile:
    # Save ra and arguments
    addiu $sp, $sp, -20
    sw $ra, 16($sp) # ra
    sw $a3, 12($sp) # type
    sw $a2, 8($sp) # y
    sw $a1, 4($sp) # x
    sw $a0, 0($sp) # letter

    # Choose codepath based on $a3 (tile type)
    beq $a3, TILE_GUESS, tile_type_guess
    beq $a3, TILE_GRAY, tile_type_gray
    beq $a3, TILE_YELLOW, tile_type_yellow
    beq $a3, TILE_GREEN, tile_type_green
    j tile_type_empty # Unknown type: just treat as empty

    # Load appropriate colors and jump to draw handler based on type (in $a3)
    tile_type_empty:
        li $t0, COLOR_LIGHT_GRAY
        j tile_draw_bordered
    tile_type_guess:
        li $t0, COLOR_DARK_GRAY
        j tile_draw_bordered
    tile_type_gray:
        li $t0, COLOR_GRAY
        j tile_draw_solid
    tile_type_yellow:
        li $t0, COLOR_YELLOW
        j tile_draw_solid
    tile_type_green:
        li $t0, COLOR_GREEN
        j tile_draw_solid

    # Draw bordered tile (TILE_EMPTY, TILE_GUESS)
    tile_draw_bordered:
        # Outer border rectangle with color in $t2
        move $a0, $a1 # x
        move $a1, $a2 # y
        li $a2, TILE_SIZE # w
        li $a3, TILE_SIZE # h
        addiu $sp, $sp, -20
        sw $t0, 16($sp) # border color in $t2
        jal gfx_draw_rect
        addiu $sp, $sp, 20

        # Inner white rectangle
        lw $a0, 4($sp) # restore x
        lw $a1, 8($sp) # restore y
        addiu $a0, $a0, 2 # x + 2
        addiu $a1, $a1, 2 # y + 2
        li $a2, TILE_INNER_SIZE # TILE_SIZE - 4
        li $a3, TILE_INNER_SIZE # TILE_SIZE - 4
        addiu $sp, $sp, -20
        li $t0, COLOR_WHITE
        sw $t0, 16($sp)
        jal gfx_draw_rect
        addiu $sp, $sp, 20

        # Draw the letter in black, centered horizontally
        lw $a0, 0($sp) # letter
        lw $a1, 4($sp) # x
        lw $a2, 8($sp) # y
        addiu $a1, $a1, 8 # x + 8 (center 16px glyph in 28px tile)
        addiu $a2, $a2, 2 # y + 2
        li $a3, COLOR_BLACK # text color
        jal gfx_draw_char

        j tile_rtn

    # Draw solid colored tile + white letter (TILE_GRAY, TILE_YELLOW TILE_GREEN)
    tile_draw_solid:
        # Draw 28x28 solid rect at (x,y) with color in $t0
        move $a0, $a1 # x
        move $a1, $a2 # y
        li $a2, TILE_SIZE
        li $a3, TILE_SIZE
        addiu $sp, $sp, -20
        sw $t0, 16($sp) # fill color
        jal gfx_draw_rect
        addiu $sp, $sp, 20

        # Draw the letter in white, centered horizontally
        lw $a0, 0($sp) # letter
        lw $a1, 4($sp) # x
        lw $a2, 8($sp) # y
        addiu $a1, $a1, 8 # x + 8 (center 16px glyph in 28px tile)
        addiu $a2, $a2, 2 # y + 2
        li $a3, COLOR_WHITE # text color
        jal gfx_draw_char

    tile_rtn:
        lw $ra, 16($sp) # restore $ra
        addiu $sp, $sp, 20
        jr $ra # return

gfx_draw_board:
    li $t0, 0 # row index (0-5)
    li $t3, 36 # starting y position

    # save return address
    addiu $sp, $sp, -4
    sw $ra, 0($sp)

    yy_loop:
        li $t1, 0 # column index (0-4)	
        li $t2, 52 # starting x position

        xx_loop:
            li $a0, 0 # blank letter
            move $a1, $t2 # x-coordinate of this tile
            move $a2, $t3 # y-coordinate of this tile
            li $a3, TILE_EMPTY # empty tile color
            
            addiu $sp, $sp, -16
            sw $t2, 12($sp) # save current x
            sw $t3, 8($sp) # save current y
            sw $t0, 4($sp) # save row counter
            sw $t1 0($sp) # save column counter

            jal gfx_draw_tile
            
            lw $t1, 0($sp) # restore row index
            lw $t0, 4($sp) # restore column index
            lw $t3, 8($sp) # restore x position
            lw $t2, 12($sp) # restore y position
            addiu $sp, $sp, 16
            
            addi $t2, $t2, 31 # move to next position for x
            addi $t1, $t1, 1 # increment column counter
            
            blt $t1, 5, xx_loop # loop over 5 columns
            
        addi $t3, $t3, 31 # move to next row
        addi $t0, $t0, 1 # increment row
        
        blt $t0, 6, yy_loop # loop over 6 rows

    # restore $ra and return
    lw $ra, 0($sp)
    addiu $sp, $sp, 4
    jr $ra